function splitNum(num: number): number {
    const s: string[] = String(num).split('');
    s.sort();
    const ans: number[] = Array(2).fill(0);
    for (let i = 0; i < s.length; ++i) {
        ans[i & 1] = ans[i & 1] * 10 + Number(s[i]);
    }
    return ans[0] + ans[1];
}

impl Solution {
    pub fn split_num(num: i32) -> i32 {
        let mut s = num.to_string().into_bytes();
        s.sort_unstable();

        let mut ans = vec![0; 2];
        for (i, c) in s.iter().enumerate() {
            ans[i & 1] = ans[i & 1] * 10 + ((c - b'0') as i32);
        }

        ans[0] + ans[1]
    }
}

class Solution(object):
    def splitNum(self, num):
        """
        :type num: int
        :rtype: int
        """
        num1, num2 = 0, 0
        for i, num in enumerate(sorted(list(str(num)))):
            if i % 2 == 0:
                num1 = num1 * 10 + int(num)
            else:
                num2 = num2 * 10 + int(num)
        return num1 + num2
